arguments.command:
cat > /tmp/getpdf2.py <<'PY'
import json,re,requests,os,unicodedata,difflib,concurrent.futures
from bs4 import BeautifulSoup
items=json.load(open('/tmp/iccv/items.json'));s=BeautifulSoup(open('/tmp/open.html').read(),'html.parser')
def norm(x): return re.sub(r'[^a-z0-9]','',unicodedata.normalize('NFKD',x).encode('ascii','ignore').decode().lower())
mp={norm(dt.get_text(' ',strip=True)):dt for dt in s.select('dt.ptitle')}
for x in items:
 d=mp.get(norm(x['title']))
 if not d:
  k=max(mp,key=lambda z:difflib.SequenceMatcher(None,norm(x['title']),z).ratio()); d=mp[k]
 a=d.find_next('a',string='pdf');x['pdf']='https://openaccess.thecvf.com'+a['href']
def dl(x):
 p='/tmp/iccv/pdf/'+x['id']+'.pdf'
 if os.path.exists(p) and os.path.getsize(p)>10000:return x['id'],os.path.getsize(p)
 r=requests.get(x['pdf'],timeout=60);open(p,'wb').write(r.content);return x['id'],len(r.content)
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
 for z in ex.map(dl,items):print(z,flush=True)
open('/tmp/iccv/items2.json','w').write(json.dumps(items,indent=2))
PY
python3 /tmp/getpdf2.py
rm -rf /tmp/iccv/txt; mkdir /tmp/iccv/txt
for f in /tmp/iccv/pdf/*.pdf; do pdftotext -f 1 -l 2 -layout "$f" "/tmp/iccv/txt/$(basename "${f%.pdf}").txt"; done
grep -iEl 'Shanghai Jiao|Fudan' /tmp/iccv/txt/*.txt || true

pip install --quiet pypdf && cat > /tmp/extract.py <<'PY'
from pypdf import PdfReader
import glob,os
for f in glob.glob('/tmp/iccv/pdf/*.pdf'):
 try:
  r=PdfReader(f);t='\n'.join((p.extract_text() or '') for p in r.pages[:2]);open('/tmp/iccv/txt/'+os.path.basename(f)[:-4]+'.txt','w').write(t)
 except Exception as e:print(f,e)
PY
python3 /tmp/extract.py
grep -iEl 'Shanghai Jiao|Fudan' /tmp/iccv/txt/*.txt || true
